/**
 * Messages, cut 6 (email in, `to-dos/gc-mode/messages/BUILD_PLAN.md` → Cut 6, the mock-up `email-in-mockups.html` on
 * branch spike/gc-mode): one Gmail message, as the API's `users.messages.get` with `format=full` returns it, read into
 * an email: its addresses, its subject, its words, the links in it and its files. Pure: the `gmail-sync` edge function
 * fetches the message and passes it here.
 *
 * The words are the plain part when there is one, else the HTML part read as text. A file is any part with a file name,
 * or one sent as an attachment, or a picture placed in the body (a signature's logo); its bytes stay in Gmail until the
 * reader fetches them by `attachmentId`.
 */

export interface GmailHeader {
  name: string
  value: string
}

export interface GmailBody {
  attachmentId?: string
  size?: number
  /** The part's bytes in base64url, for a part Gmail sends inline (the words, a small file). */
  data?: string
}

export interface GmailPart {
  partId?: string
  mimeType?: string
  filename?: string
  headers?: GmailHeader[]
  body?: GmailBody
  parts?: GmailPart[]
}

export interface GmailMessage {
  id: string
  threadId?: string
  labelIds?: string[]
  /** When Gmail took it, in milliseconds since 1970, as a string. */
  internalDate?: string
  payload?: GmailPart
}

export interface EmailAddress {
  /** The display name, or null when the header gives none. */
  name: string | null
  address: string
}

export interface EmailFile {
  partId: string
  name: string
  mime: string
  size: number
  /** Gmail's id for the bytes (`users.messages.attachments.get`). Null when they came in the part. */
  attachmentId: string | null
  /** The bytes in base64url when Gmail sent them in the part. */
  data: string | null
  /** A picture placed in the body (a Content-ID, or inline), as a signature's logo is. */
  inline: boolean
}

export interface EmailIn {
  gmailId: string
  threadId: string | null
  labels: string[]
  /** When Gmail took it, ISO. Null when Gmail gave no time. */
  at: string | null
  from: EmailAddress | null
  to: EmailAddress[]
  cc: EmailAddress[]
  subject: string
  text: string
  /** Every http(s) link in the words or behind the HTML's links, once each, in order. */
  links: string[]
  files: EmailFile[]
  /** The message's own headers by lower-case name, the first of each. */
  headers: Readonly<Record<string, string>>
}

/** The most words a line keeps: the rest of a very long email stays in Gmail. */
export const EMAIL_TEXT_MAX = 100_000

const headerMap = (headers: readonly GmailHeader[] | undefined): Record<string, string> => {
  const out: Record<string, string> = {}
  for (const h of headers ?? []) {
    const key = h.name.trim().toLowerCase()
    if (key && !(key in out)) out[key] = h.value
  }
  return out
}

/** base64url (or plain base64) to bytes. Malformed input reads as no bytes. */
export function base64UrlBytes(data: string): Uint8Array {
  try {
    const b64 = data.replace(/-/g, '+').replace(/_/g, '/').replace(/\s+/g, '')
    const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4))
    const bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
    return bytes
  } catch {
    return new Uint8Array(0)
  }
}

const decode = (bytes: Uint8Array, charset: string | null): string => {
  try {
    return new TextDecoder(charset || 'utf-8').decode(bytes)
  } catch {
    return new TextDecoder('utf-8').decode(bytes)
  }
}

const charsetOf = (contentType: string | undefined): string | null => /charset="?([^";\s]+)"?/i.exec(contentType ?? '')?.[1] ?? null

/**
 * RFC 2047's encoded words (`=?UTF-8?B?…?=`, `=?ISO-8859-1?Q?…?=`) read as text. A header Gmail already decoded passes
 * through as it is.
 */
export function decodeHeaderWords(value: string): string {
  return value
    .replace(/(=\?[^?]+\?[bBqQ]\?[^?]*\?=)\s+(?==\?)/g, '$1')
    .replace(/=\?([^?]+)\?([bBqQ])\?([^?]*)\?=/g, (_m, charset: string, enc: string, text: string) => {
      if (enc.toUpperCase() === 'B') return decode(base64UrlBytes(text), charset)
      const bytes: number[] = []
      const q = text.replace(/_/g, ' ')
      for (let i = 0; i < q.length; i++) {
        if (q[i] === '=' && /^[0-9a-fA-F]{2}$/.test(q.slice(i + 1, i + 3))) {
          bytes.push(parseInt(q.slice(i + 1, i + 3), 16))
          i += 2
        } else bytes.push(q.charCodeAt(i) & 0xff)
      }
      return decode(new Uint8Array(bytes), charset)
    })
}

/** One address as a header or a forwarded block writes it: `Name <a@b>`, `"Last, First" <a@b>`, `a@b`, `Name [mailto:a@b]`. */
export function parseAddress(raw: string): EmailAddress | null {
  const text = decodeHeaderWords(raw).trim()
  const bracket = /^(.*?)[<[]\s*(?:mailto:)?([^<>[\]\s]+@[^<>[\]\s]+?)\s*[>\]]\s*$/i.exec(text)
  if (bracket) {
    const name = bracket[1]!.trim().replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1').trim()
    return { name: name || null, address: bracket[2]!.trim() }
  }
  const bare = /^(?:mailto:)?([^\s<>"',;]+@[^\s<>"',;]+)$/i.exec(text)
  return bare ? { name: null, address: bare[1]! } : null
}

/** A header's list of addresses: commas split it, except inside quotes or angle brackets. */
export function parseAddressList(raw: string | undefined): EmailAddress[] {
  if (!raw) return []
  const parts: string[] = []
  let depth = 0
  let quoted = false
  let cur = ''
  for (const ch of raw) {
    if (ch === '"') quoted = !quoted
    else if (!quoted && ch === '<') depth++
    else if (!quoted && ch === '>') depth = Math.max(0, depth - 1)
    if ((ch === ',' || ch === ';') && !quoted && depth === 0) {
      parts.push(cur)
      cur = ''
    } else cur += ch
  }
  parts.push(cur)
  return parts.map((p) => parseAddress(p)).filter((a): a is EmailAddress => a !== null)
}

const ENTITIES: Readonly<Record<string, string>> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '-', mdash: '-', hellip: '...', rsquo: "'", lsquo: "'", rdquo: '"', ldquo: '"' }

/** HTML's entities read as the characters they stand for. */
export function decodeEntities(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e: string) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10)
      return Number.isFinite(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : m
    }
    return ENTITIES[e.toLowerCase()] ?? m
  })
}

/** An HTML body read as text: a paragraph, a break, a row or a list item each start a line. */
export function htmlToText(html: string): string {
  const text = html
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(script|style|head|title)\b[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<li\b[^>]*>/gi, '\n- ')
    .replace(/<\/(p|div|tr|h[1-6]|table|blockquote|ul|ol|pre)\s*>/gi, '\n')
    .replace(/<(p|div|tr|h[1-6]|table|blockquote|ul|ol|pre)\b[^>]*>/gi, '\n')
    .replace(/<\/t[dh]\s*>/gi, ' ')
    .replace(/<[^>]+>/g, '')
  return tidy(decodeEntities(text))
}

/** Each line trimmed of trailing space, no more than one empty line in a row, none at either end. */
const tidy = (text: string): string =>
  text
    .replace(/\r\n?/g, '\n')
    .replace(/ /g, ' ')
    .split('\n')
    .map((l) => l.replace(/[ \t]+$/, ''))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()

const URL_IN_TEXT = /https?:\/\/[^\s<>"'()]+[^\s<>"'().,;:!?]/gi
const HREF = /<a\b[^>]*\bhref\s*=\s*(["'])(https?:\/\/[^"']+)\1/gi

const isAttachment = (part: GmailPart, headers: Record<string, string>): boolean =>
  Boolean(part.filename) || /^\s*attachment/i.test(headers['content-disposition'] ?? '')

/** One Gmail message read into an email. */
export function readGmailMessage(m: GmailMessage): EmailIn {
  const headers = headerMap(m.payload?.headers)
  const plain: string[] = []
  const html: string[] = []
  const files: EmailFile[] = []

  const walk = (part: GmailPart) => {
    const mime = (part.mimeType ?? '').toLowerCase()
    const own = headerMap(part.headers)
    if (mime.startsWith('multipart/')) {
      for (const kid of part.parts ?? []) walk(kid)
      return
    }
    const attached = isAttachment(part, own)
    if (!attached && (mime === 'text/plain' || mime === 'text/html')) {
      const words = decode(base64UrlBytes(part.body?.data ?? ''), charsetOf(own['content-type']))
      ;(mime === 'text/plain' ? plain : html).push(words)
      return
    }
    if (!part.body?.attachmentId && !part.body?.data) return
    const disposition = own['content-disposition'] ?? ''
    const inline = !/^\s*attachment/i.test(disposition) && (/^\s*inline/i.test(disposition) || Boolean(own['content-id']))
    files.push({
      partId: part.partId ?? '',
      name: decodeHeaderWords(part.filename || '').trim() || (inline ? 'picture' : 'file'),
      mime: mime || 'application/octet-stream',
      size: part.body?.size ?? 0,
      attachmentId: part.body?.attachmentId ?? null,
      data: part.body?.attachmentId ? null : (part.body?.data ?? null),
      inline,
    })
  }
  if (m.payload) walk(m.payload)

  const text = plain.length > 0 ? tidy(plain.join('\n\n')) : htmlToText(html.join('\n'))
  const links: string[] = []
  const seen = new Set<string>()
  const add = (url: string) => {
    const u = decodeEntities(url).trim()
    if (!seen.has(u)) {
      seen.add(u)
      links.push(u)
    }
  }
  for (const words of html) for (const hit of words.matchAll(HREF)) add(hit[2]!)
  for (const hit of text.matchAll(URL_IN_TEXT)) add(hit[0])

  const ms = Number(m.internalDate)
  return {
    gmailId: m.id,
    threadId: m.threadId ?? null,
    labels: [...(m.labelIds ?? [])],
    at: Number.isFinite(ms) && ms > 0 ? new Date(ms).toISOString() : null,
    from: parseAddressList(headers['from'])[0] ?? null,
    to: parseAddressList(headers['to']),
    cc: parseAddressList(headers['cc']),
    subject: decodeHeaderWords(headers['subject'] ?? '').trim(),
    text: text.length > EMAIL_TEXT_MAX ? `${text.slice(0, EMAIL_TEXT_MAX)}\n\n[The rest of this email is in Gmail.]` : text,
    links,
    files,
    headers,
  }
}
